// Marble maze: tip the frame to roll a marble through a maze into its hole.
//
// On a fast screen with an accelerometer the marble rolls: it speeds up the
// way the frame leans, bounces off the walls and drops into the hole when it
// rolls over it slowly enough. Everywhere else (e-paper, where each picture
// is a refresh, and a frame without an accelerometer) it moves a corridor at
// a time: a tilt, a flick, a swipe or an arrow key sends it that way until a
// wall or a turning stops it. A tap or a key after the hole deals a new maze.
//
// The maze is made on the frame from a seed (a depth-first walk, so there is
// one way between any two cells), the hole put where the walk went deepest.
import { makeMaze, N, E, S, W } from './maze'

type Maze = ReturnType<typeof makeMaze>

type Game = { seed: number; x: number; y: number; moves: number; solved: boolean; level: number }

// The maze shown, kept while the interpreter lives and made again from its
// seed when it is gone.
let mazeKey = ''
let maze: Maze | null = null
let wallsPath = ''
// The rolling marble, in maze pixels, and when it last moved.
let mx = -1
let my = -1
let vx = 0
let vy = 0
let lastAt = 0
let rolledFor = ''
let cellSize = 0

const accelerometer = () => (typeof frameos.accelerometer === 'function' ? frameos.accelerometer() : null)

const DIRS: Record<string, [number, number, number]> = {
  up: [0, -1, N],
  right: [1, 0, E],
  down: [0, 1, S],
  left: [-1, 0, W],
}

function readGame(app: any): Game {
  const g = app.state.game
  if (g && typeof g === 'object' && typeof g.seed === 'number') {
    return {
      seed: g.seed | 0,
      x: g.x | 0,
      y: g.y | 0,
      moves: g.moves | 0,
      solved: !!g.solved,
      level: Math.max(1, g.level | 0),
    }
  }
  return { seed: (Date.now() % 2147483647) | 0, x: 0, y: 0, moves: 0, solved: false, level: 1 }
}

/** The maze's place on the panel: its cells' size and where it starts. */
function geometry(W: number, H: number, round: boolean, fast: boolean, size: string) {
  const Smin = Math.min(W, H)
  const scale = size === 'small' ? 1.35 : size === 'large' ? 0.72 : 1
  let ax = 0
  let ay = 0
  let aw = W
  let ah = H
  if (round) {
    const side = Math.floor((Smin / 2 - 12) * Math.SQRT2)
    ax = (W - side) / 2
    ay = (H - side) / 2
    aw = side
    ah = side
  } else {
    const m = Math.round(Smin * 0.04)
    const header = Math.round(Math.max(28, Smin * 0.08))
    ax = m
    ay = m + header
    aw = W - 2 * m
    ah = H - 2 * m - header
  }
  const want = (fast ? Smin / 9 : Smin / 8) * scale
  const cols = Math.max(3, Math.floor(aw / want))
  const rows = Math.max(3, Math.floor(ah / want))
  const cs = Math.floor(Math.min(aw / cols, ah / rows))
  const ox = Math.round(ax + (aw - cs * cols) / 2)
  const oy = Math.round(ay + (ah - cs * rows) / 2)
  return { cols, rows, cs, ox, oy }
}

/** The walls as one filled path: a bar for each cell's top and left side,
 * then the far edges, `t` thick. Filled, not stroked: a stroke is outlined
 * again at every frame, which cost a rolling marble a third of its frame on
 * an ESP32 even where only the marble moved. */
function pathOf(m: Maze, cs: number, t: number): string {
  const h = t / 2
  const bar = (x: number, y: number, w: number, hh: number) => `M${x} ${y}h${w}v${hh}h${-w}Z`
  let d = ''
  for (let y = 0; y < m.rows; y++) {
    for (let x = 0; x < m.cols; x++) {
      const w = m.walls[y * m.cols + x]
      if (w & N) d += bar(x * cs - h, y * cs - h, cs + t, t)
      if (w & W) d += bar(x * cs - h, y * cs - h, t, cs + t)
    }
  }
  d += bar(m.cols * cs - h, -h, t, m.rows * cs + t) + bar(-h, m.rows * cs - h, m.cols * cs + t, t)
  return d
}

/** One move a corridor long: until a wall, a turning, or the hole. */
function slide(m: Maze, game: Game, dir: string): boolean {
  const [dx, dy, bit] = DIRS[dir]
  let x = game.x
  let y = game.y
  let steps = 0
  while (!(m.walls[y * m.cols + x] & bit)) {
    x += dx
    y += dy
    steps++
    if (x === m.holeX && y === m.holeY) break
    // A way to turn off: stop here, the person decides.
    const w = m.walls[y * m.cols + x]
    const sides = dx !== 0 ? (w & N ? 0 : 1) + (w & S ? 0 : 1) : (w & E ? 0 : 1) + (w & W ? 0 : 1)
    if (sides > 0) break
  }
  if (!steps) return false
  game.x = x
  game.y = y
  game.moves++
  game.solved = x === m.holeX && y === m.holeY
  return true
}

function newMaze(app: any, game: Game) {
  const next: Game = { seed: (game.seed * 48271 + 11) % 2147483647, x: 0, y: 0, moves: 0, solved: false, level: game.level + 1 }
  frameos.setState('game', next)
  mx = -1
}

/** The rolling marble: a step of `dt` seconds under gravity (gx, gy). */
function roll(m: Maze, cs: number, gx: number, gy: number, dt: number): boolean {
  const r = cs * 0.3
  const wt = Math.max(2, cs * 0.06)
  const accel = cs * 16
  const bounce = 0.35
  vx += gx * accel * dt
  vy += gy * accel * dt
  const damp = Math.exp(-1.4 * dt)
  vx *= damp
  vy *= damp
  const top = cs * 14
  const speed = Math.hypot(vx, vy)
  if (speed > top) {
    vx *= top / speed
    vy *= top / speed
  }
  const steps = Math.max(1, Math.ceil((Math.max(Math.abs(vx), Math.abs(vy)) * dt) / (r * 0.4)))
  const h = dt / steps
  for (let k = 0; k < steps; k++) {
    mx += vx * h
    my += vy * h
    const cx = Math.max(0, Math.min(m.cols - 1, Math.floor(mx / cs)))
    const cy = Math.max(0, Math.min(m.rows - 1, Math.floor(my / cs)))
    const w = m.walls[cy * m.cols + cx]
    const left = cx * cs + wt + r
    const right = (cx + 1) * cs - wt - r
    const upper = cy * cs + wt + r
    const lower = (cy + 1) * cs - wt - r
    if (w & E && mx > right) {
      mx = right
      if (vx > 0) vx = -vx * bounce
    }
    if (w & W && mx < left) {
      mx = left
      if (vx < 0) vx = -vx * bounce
    }
    if (w & S && my > lower) {
      my = lower
      if (vy > 0) vy = -vy * bounce
    }
    if (w & N && my < upper) {
      my = upper
      if (vy < 0) vy = -vy * bounce
    }
    // The ends of the walls beside an opening: round posts.
    for (let py = cy; py <= cy + 1; py++) {
      for (let px = cx; px <= cx + 1; px++) {
        if (!m.posts[py * (m.cols + 1) + px]) continue
        const dx = mx - px * cs
        const dy = my - py * cs
        const d = Math.hypot(dx, dy)
        const min = r + wt
        if (d >= min || d === 0) continue
        const nx = dx / d
        const ny = dy / d
        mx = px * cs + nx * min
        my = py * cs + ny * min
        const vn = vx * nx + vy * ny
        if (vn < 0) {
          vx -= (1 + bounce) * vn * nx
          vy -= (1 + bounce) * vn * ny
        }
      }
    }
  }
  // Over the hole and slow enough: in.
  const hx = (m.holeX + 0.5) * cs
  const hy = (m.holeY + 0.5) * cs
  return Math.hypot(mx - hx, my - hy) < cs * 0.22 && Math.hypot(vx, vy) < cs * 9
}

export function get(app: any, context: any) {
  const Wd = context.imageWidth || app.frame.width
  const Hd = context.imageHeight || app.frame.height
  const round = context.round === true
  const fast = app.frame.fast ?? !app.frame.paper
  const size = String(app.config.size || 'medium')
  const g = accelerometer()
  const rolling = fast && !!g
  const game = readGame(app)
  if (!app.state.game) frameos.setState('game', game)
  const geo = geometry(Wd, Hd, round, fast, size)
  const { cs, ox, oy } = geo
  cellSize = cs
  const key = [game.seed, geo.cols, geo.rows, cs].join(':')
  if (key !== mazeKey || !maze) {
    mazeKey = key
    maze = makeMaze(geo.cols, geo.rows, game.seed)
    wallsPath = pathOf(maze, cs, Math.max(3, cs * 0.12))
    mx = -1
  }
  const m = maze
  if (game.x >= m.cols || game.y >= m.rows) {
    // Another size of maze: start it from the top.
    game.x = 0
    game.y = 0
    game.moves = 0
    game.solved = false
    frameos.setState('game', game)
  }
  const gameKey = `${key}:${game.level}`
  if (mx < 0 || rolledFor !== gameKey) {
    // Where the game says, or where it was when the interpreter went.
    const kept = frameos.recall('marble')
    if (kept && kept.key === gameKey && rolling) {
      mx = kept.x
      my = kept.y
    } else {
      mx = (Math.min(game.x, m.cols - 1) + 0.5) * cs
      my = (Math.min(game.y, m.rows - 1) + 0.5) * cs
    }
    vx = 0
    vy = 0
    rolledFor = gameKey
    lastAt = Date.now()
  }

  if (rolling && !game.solved) {
    const now = Date.now()
    const dt = Math.min(0.1, Math.max(0.001, (now - lastAt) / 1000))
    lastAt = now
    const was = [Math.floor(mx / cs), Math.floor(my / cs)]
    if (roll(m, cs, g.x, g.y, dt)) {
      game.x = m.holeX
      game.y = m.holeY
      game.solved = true
      mx = (m.holeX + 0.5) * cs
      my = (m.holeY + 0.5) * cs
      frameos.setState('game', game)
    } else if (Math.floor(mx / cs) !== was[0] || Math.floor(my / cs) !== was[1]) {
      frameos.remember('marble', { key: gameKey, x: mx, y: my })
    }
  } else if (!rolling) {
    mx = (game.x + 0.5) * cs
    my = (game.y + 0.5) * cs
  }
  // A rolling marble wants the next frame; a solved maze or a corridor move waits.
  if (!rolling || game.solved) frameos.setNextSleep(3600)

  const paper = !fast
  const r = cs * 0.3
  const back = paper ? '#ffffff' : '#1c2b22'
  const floor = paper ? '#ffffff' : '#2f4a38'
  const wall = paper ? '#000000' : '#d9c7a0'
  const ink = paper ? '#000000' : '#eef3ea'
  const hx = ox + (m.holeX + 0.5) * cs
  const hy = oy + (m.holeY + 0.5) * cs
  const Smin = Math.min(Wd, Hd)
  const moves = `${game.moves} ${game.moves === 1 ? 'move' : 'moves'}`
  const status = game.solved
    ? round ? `In! ${moves}` : `In the hole in ${moves}`
    : rolling
      ? round ? 'Roll it to the hole' : 'Tilt to roll the marble into the hole'
      : g
        ? `Tilt or swipe · ${moves}`
        : round ? `Swipe · ${moves}` : `Swipe or use the arrow keys · ${moves}`
  const next = round ? 'Tap for the next' : 'Tap or press a key for the next maze'
  let font = Math.round(Math.max(16, Smin * (round ? 0.045 : 0.05)))
  const statusY = round ? oy - font * 0.9 : Math.round(Smin * 0.04) + font
  if (round) {
    // The arc above the maze is narrow: a line as wide as the glass is there.
    const dy = Math.abs(statusY - font - Hd / 2)
    const r0 = Smin / 2 - 12
    const chord = 2 * Math.sqrt(Math.max(0, r0 * r0 - dy * dy))
    font = Math.max(12, Math.min(font, Math.floor(chord / (Math.max(status.length, next.length) * 0.55))))
  }

  return (
    <svg viewBox={`0 0 ${Wd} ${Hd}`} width={Wd} height={Hd}>
      <rect x={0} y={0} width={Wd} height={Hd} fill={back} />
      <rect x={ox} y={oy} width={m.cols * cs} height={m.rows * cs} fill={floor} />
      <circle cx={hx} cy={hy} r={cs * 0.36} fill={paper ? '#000000' : '#0b120d'} />
      {paper ? <circle cx={hx} cy={hy} r={cs * 0.24} fill="#ffffff" /> : null}
      {paper ? <circle cx={hx} cy={hy} r={cs * 0.14} fill="#000000" /> : null}
      <path d={wallsPath} transform={`translate(${ox} ${oy})`} fill={wall} />
      {game.solved ? null : (
        <g>
          {/* Solid circles, no gradient: a gradient is painted per pixel at every frame. */}
          <circle cx={ox + mx} cy={oy + my} r={r} fill={paper ? '#000000' : '#4d6489'} />
          {paper ? null : <circle cx={ox + mx - r * 0.18} cy={oy + my - r * 0.2} r={r * 0.68} fill="#8aa3c6" />}
          <circle cx={ox + mx - r * 0.3} cy={oy + my - r * 0.3} r={r * 0.28} fill={paper ? '#ffffff' : '#eef4fb'} />
        </g>
      )}
      <text x={Wd / 2} y={statusY} fontSize={font} textAnchor="middle" fill={ink}>
        {status}
      </text>
      {game.solved ? (
        <text x={Wd / 2} y={round ? oy + m.rows * cs + font * 1.4 : Hd - Math.round(Smin * 0.02)} fontSize={font}
          fontWeight="bold" textAnchor="middle" fill={ink}>
          {next}
        </text>
      ) : null}
    </svg>
  )
}

const SWIPE: Record<string, string> = { up: 'up', down: 'down', left: 'left', right: 'right' }
const KEYS: Record<string, string> = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' }

export function onEvent(app: any, context: any) {
  const e = context.event
  const p = context.payload || {}
  const game = readGame(app)
  if (game.solved) {
    if (e === 'tap' || e === 'shake' || (e === 'button' && p.action === 'press') ||
        (e === 'keyDown' && !p.repeat)) {
      newMaze(app, game)
      return true
    }
    return false
  }
  let dir = ''
  if (e === 'tilt' || e === 'flick' || e === 'swipe') dir = SWIPE[p.direction] || ''
  else if (e === 'keyDown') dir = KEYS[p.code] || ''
  if (!dir || !maze) return false
  // A rolling marble is moved by the frame itself; a tilt says nothing new.
  if ((e === 'tilt' || e === 'flick') && (app.frame.fast ?? !app.frame.paper) && accelerometer()) return false
  // From the cell the marble is in: a rolling one may be anywhere.
  if (mx >= 0 && cellSize > 0) {
    game.x = Math.max(0, Math.min(maze.cols - 1, Math.floor(mx / cellSize)))
    game.y = Math.max(0, Math.min(maze.rows - 1, Math.floor(my / cellSize)))
  }
  if (!slide(maze, game, dir)) return false
  frameos.setState('game', game)
  frameos.remember('marble', null)
  mx = -1
  return true
}

