// A maze from a seed: a depth-first walk that knocks a wall down into each
// cell it has not been to, so every cell is reached by exactly one way. The
// hole goes where the walk from the start (the top left) went deepest.

export const N = 1
export const E = 2
export const S = 4
export const W = 8

export type Maze = {
  cols: number
  rows: number
  /** Each cell's walls: N, E, S, W bits. */
  walls: Uint8Array
  /** For each corner of the grid, (cols + 1) x (rows + 1): whether a wall ends or meets there. */
  posts: Uint8Array
  holeX: number
  holeY: number
}

/** mulberry32: a generator whose whole state is one integer. */
function generator(seed: number) {
  let s = seed | 0
  return () => {
    let t = (s = (s + 0x6d2b79f5) | 0)
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function makeMaze(cols: number, rows: number, seed: number): Maze {
  const random = generator(seed)
  const walls = new Uint8Array(cols * rows).fill(N | E | S | W)
  const depth = new Int32Array(cols * rows).fill(-1)
  const stack: number[] = [0]
  depth[0] = 0
  let deepest = 0
  const options: number[] = []
  while (stack.length) {
    const here = stack[stack.length - 1]
    const x = here % cols
    const y = (here / cols) | 0
    options.length = 0
    if (y > 0 && depth[here - cols] < 0) options.push(N)
    if (x < cols - 1 && depth[here + 1] < 0) options.push(E)
    if (y < rows - 1 && depth[here + cols] < 0) options.push(S)
    if (x > 0 && depth[here - 1] < 0) options.push(W)
    if (!options.length) {
      stack.pop()
      continue
    }
    const way = options[Math.floor(random() * options.length)]
    const next = way === N ? here - cols : way === E ? here + 1 : way === S ? here + cols : here - 1
    const back = way === N ? S : way === E ? W : way === S ? N : E
    walls[here] &= ~way
    walls[next] &= ~back
    depth[next] = depth[here] + 1
    if (depth[next] > depth[deepest]) deepest = next
    stack.push(next)
  }
  // Where walls meet: the corners the marble can catch on.
  const posts = new Uint8Array((cols + 1) * (rows + 1))
  const wallAt = (x: number, y: number, bit: number) =>
    x >= 0 && y >= 0 && x < cols && y < rows && (walls[y * cols + x] & bit) !== 0
  for (let py = 0; py <= rows; py++) {
    for (let px = 0; px <= cols; px++) {
      const touches =
        wallAt(px - 1, py - 1, E) || wallAt(px, py - 1, W) || wallAt(px - 1, py, E) || wallAt(px, py, W) ||
        wallAt(px - 1, py - 1, S) || wallAt(px - 1, py, N) || wallAt(px, py - 1, S) || wallAt(px, py, N)
      posts[py * (cols + 1) + px] = touches ? 1 : 0
    }
  }
  return { cols, rows, walls, posts, holeX: deepest % cols, holeY: (deepest / cols) | 0 }
}
